import React, { useEffect, useRef } from 'react';
import { useSiteMetadata } from '../../../hooks';

const Comments = ({ postTitle, postSlug }) => {
  const { giscus } = useSiteMetadata();
  const containerRef = useRef(null);

  useEffect(() => {
    if (!giscus || !giscus.repo || !giscus.repoId || !giscus.category || !giscus.categoryId) return;
    const el = containerRef.current;
    if (!el || typeof document === 'undefined') return;

    // clear previous instance when navigating between posts
    while (el.firstChild) el.removeChild(el.firstChild);

    const script = document.createElement('script');
    script.src = 'https://giscus.app/client.js';
    script.async = true;
    script.crossOrigin = 'anonymous';

    script.setAttribute('data-repo', giscus.repo);
    script.setAttribute('data-repo-id', giscus.repoId);
    script.setAttribute('data-category', giscus.category);
    script.setAttribute('data-category-id', giscus.categoryId);

    script.setAttribute('data-mapping', giscus.mapping || 'pathname');
    script.setAttribute('data-strict', giscus.strict || '0');
    script.setAttribute('data-reactions-enabled', giscus.reactionsEnabled || '1');
    script.setAttribute('data-emit-metadata', giscus.emitMetadata || '0');
    script.setAttribute('data-input-position', giscus.inputPosition || 'bottom');
    script.setAttribute('data-theme', giscus.theme || 'preferred_color_scheme');
    if (giscus.lang) script.setAttribute('data-lang', giscus.lang);
    if (giscus.loading) script.setAttribute('data-loading', giscus.loading);

    el.appendChild(script);

    return () => {
      while (el.firstChild) el.removeChild(el.firstChild);
    };
  }, [giscus, postSlug, postTitle]);

  if (!giscus || !giscus.repo || !giscus.repoId || !giscus.category || !giscus.categoryId) {
    return null;
  }

  return <div ref={containerRef} />;
};

export default Comments;
